function evaluateProperty({api}) {
	if(api.data.get_article_details_1.articleDetails) {
		const {displayAttachments, hasAttachments} = api.data.get_article_details_1.articleDetails.articleInfo;
		const { overridePageProperties, showAttachments } = api.context.props;
		if ((displayAttachments && hasAttachments)) {
			return overridePageProperties ? !showAttachments : false;
		}
		return true;
	}
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api}) {
	const { overridePageProperties, showArticleActions } = api.context.props;
	if (api.data.get_article_details_1.articleDetails) {
		return overridePageProperties ? !showArticleActions : '';
	}
	return '';
}

function evaluateProperty({
    api
}) {
    if (api.context.props.sysId != null && api.context.props.sysId != '' && api.context.props.mode != null && api.context.props.mode == 'preview')
        return false;
    return true;
}

function evaluateProperty({
    api
}) {
    var items = [{
        "id": "copyLink",
        "label": api.state.copyLinkLabel
    }]
    if (api.data.get_article_details_1.articleDetails && api.data.get_article_details_1.articleDetails.showFlag)
        items.unshift({
            "id": "flag",
            "label": api.state.flagArticleLabel
        });
    return items;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
	if (!api.data.get_article_details_1.articleDetails || !api.data.get_article_details_1.articleDetails.languageInfo)
		return; 

	let languageInformation = api.data.get_article_details_1.articleDetails.languageInfo;
    let languages = languageInformation.langVersions;
    let selectedLanguageId = languageInformation.selectedLangVersion;
    let selectedLanguage = languages.find(language => language.id == selectedLanguageId);
    let value = '';

	if(selectedLanguage)
		 value = "Language " + selectedLanguage.label + ", Select to choose other available languages of the article";

    return {
        "aria-label": value
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
	if (!api.data.get_article_details_1.articleDetails || !api.data.get_article_details_1.articleDetails.versionInfo)
		return;

	let versionInformation = api.data.get_article_details_1.articleDetails.versionInfo;
    let versions = versionInformation.versions;
    let selectedVersionId = versionInformation.selectedVersion;
    let selectedVersion = versions.find(version => version.id == selectedVersionId);
    let value = '';

	if(selectedVersion)
		 value = "Version " + selectedVersion.label + ", Select to choose other available versions of the article";

    return {
        "aria-label": value
    };
}

function evaluateProperty({ api }) {
	const articleDetails = api.data?.get_article_details_1?.articleDetails;
	if (!articleDetails) return [];
	const secondaryFields = articleDetails.secondaryFields;
	const { overridePageProperties, showReadingTime, showViewCount, showLastUpdated, showAverageRating } = api.context.props;
	return overridePageProperties ? secondaryFields.filter(field => (field.column !== 'timeToRead' || showReadingTime) && (field.column !== 'viewCount' || showViewCount) && (field.column !== 'sysUpdatedOn' || showLastUpdated) && (field.column !== 'rating' || showAverageRating)) : secondaryFields;
}

